import json
import re
import datetime
from zoneinfo import ZoneInfo

# Knowledge layout. Folders may nest at most 2 levels, so inbox folders are top-level.
BK_SETTINGS = "Bookkeeping/settings.json"
BK_CLIENTS = "Bookkeeping/Clients"
BK_RULES = "Bookkeeping/Rules"
BK_BILLS = "Bookkeeping/Bills"
BK_INBOX = "Bookkeeping Inbox"
BK_PROCESSED = "Bookkeeping Processed"
BK_FAILED = "Bookkeeping Failed"
BK_MAIL = "Bookkeeping/Mail"


def bk_read_json(path, default=None):
    try:
        raw = api.files.read(file=path)
    except Exception:
        return default
    try:
        return json.loads(raw)
    except Exception:
        return default


def bk_answer(responses, qid):
    """A form answer: str, bool, list, or a lookup {id, label}."""
    return (responses or {}).get(qid)


def bk_client_for(settings, slug):
    client = bk_read_json(BK_CLIENTS + "/" + slug + ".json")
    if not client:
        return None
    return client


# ── Load the bill ──


todo_id = params.get("todo_id") or ""
form_id = params.get("form_id") or ""
responses = params.get("responses") or {}
problem = ""
kind = ""
if form_id == params["review_form"]:
    kind = "review"
elif form_id == params["approval_form"]:
    kind = "client"

record_todo = todo_id
record = bk_read_json(BK_BILLS + "/" + todo_id + ".json") or {}
if record.get("link"):
    record_todo = record["link"]
    record = bk_read_json(BK_BILLS + "/" + record_todo + ".json") or {}
settings = bk_read_json(BK_SETTINGS) or {}
client = bk_client_for(settings, record.get("client_slug") or "") or {}

if not kind or not todo_id or not record:
    problem = "ignored"
elif record.get("status") in ("approved", "rejected"):
    problem = "This bill was already " + record["status"] + ", so nothing was changed."

if kind == "review":
    answer = str(bk_answer(responses, "q_decision") or "").lower()
    action = ("approve_changes" if "changes" in answer else "approve" if answer.startswith("approve")
              else "reject" if answer.startswith("reject") else "ask" if answer.startswith("ask") else "")
else:
    answer = str(bk_answer(responses, "q_client_decision") or "").lower()
    action = ("client_approved" if "approved" in answer else "client_rejected" if "rejected" in answer
              else "client_question" if "question" in answer else "")
if not problem and not action:
    problem = "The form didn't say what to do with this bill."

decision = {
    "action": action,
    "changes": str(bk_answer(responses, "q_changes") or "").strip(),
    "remember": bool(bk_answer(responses, "q_remember")),
    "notes": str(bk_answer(responses, "q_notes") or bk_answer(responses, "q_client_reply") or "").strip(),
    "actor": params.get("actor") or "",
}
ctx = {"settings": settings, "client": client, "record": record, "record_todo": record_todo, "kind": kind}

# ── bookkeeping kit: shared helpers (inlined into each node by gen-ext.js) ──
import json
import re
import datetime
from zoneinfo import ZoneInfo

# Knowledge layout. Folders may nest at most 2 levels, so inbox folders are top-level.
BK_SETTINGS = "Bookkeeping/settings.json"
BK_CLIENTS = "Bookkeeping/Clients"
BK_RULES = "Bookkeeping/Rules"
BK_BILLS = "Bookkeeping/Bills"
BK_INBOX = "Bookkeeping Inbox"
BK_PROCESSED = "Bookkeeping Processed"
BK_FAILED = "Bookkeeping Failed"
BK_MAIL = "Bookkeeping/Mail"


def bk_write_json(path, data):
    api.files.put(file=path, content=json.dumps(data, indent=2, sort_keys=True))


def bk_money(value):
    """Parse 1234.5, "1,234.50", "$12" or "A$ 12.00" into a float; None when blank or not a number."""
    if value is None or isinstance(value, bool):
        return None
    if isinstance(value, (int, float)):
        return float(value)
    s = re.sub(r"[^0-9.\-]", "", str(value))
    if s in ("", "-", ".", "-."):
        return None
    try:
        return float(s)
    except ValueError:
        return None


def bk_fmt(amount, currency=""):
    if amount is None:
        return "—"
    return (currency + " " if currency else "") + "{:,.2f}".format(amount)


def bk_tz(settings):
    # The sandbox may lack the tz database; fall back to AEST (UTC+10) rather than failing the run.
    try:
        return ZoneInfo((settings or {}).get("timezone") or "Australia/Sydney")
    except Exception:
        return datetime.timezone(datetime.timedelta(hours=10))


def bk_today(settings):
    return datetime.datetime.now(bk_tz(settings)).date()


def bk_now_iso(settings):
    return datetime.datetime.now(bk_tz(settings)).replace(microsecond=0).isoformat()


def bk_add_business_days(day, n):
    d = day
    while n > 0:
        d = d + datetime.timedelta(days=1)
        if d.weekday() < 5:
            n -= 1
    return d


def bk_norm(name):
    s = re.sub(r"[^a-z0-9 ]+", " ", str(name or "").lower())
    s = re.sub(r"\b(pty|ltd|limited|p/l|the|inc|co)\b", " ", s)
    return re.sub(r"\s+", " ", s).strip()


def bk_reviewer(settings, client):
    return (client or {}).get("reviewer_id") or (settings or {}).get("reviewer_id")


# ── bookkeeping kit: Xero ledger adapter (inlined into Xero nodes by gen-ext.js) ──
# Every write passes xero_tenant_id so it lands in the client's own Xero organisation
# (myhub-mcp-servers PR #558). Reads pass it too.
import base64
from collections import Counter

XERO = "xero-accounting"
XERO_EXPENSE_TYPES = {"EXPENSE", "DIRECTCOSTS", "OVERHEADS", "FIXED", "CURRENT", "INVENTORY", "PREPAYMENT", "NONCURRENT"}
XERO_DEAD = {"DELETED", "VOIDED"}


def xero_call(tool, tenant_id=None, **args):
    if tenant_id:
        args["xero_tenant_id"] = tenant_id
    try:
        return api.connectors.invoke(server=XERO, tool=tool, args=args)
    except Exception as exc:
        raise RuntimeError(xero_error_text(exc)) from None


def xero_error_text(exc):
    """Xero's own validation messages (the useful part, at the end of a long error), else the error text."""
    text = str(exc)
    at = text.find("ValidationErrors")
    messages = []
    for m in re.findall(r'"Message"\s*:\s*"((?:[^"\\]|\\.)*)"', text[at:] if at >= 0 else ""):
        if m not in messages:
            messages.append(m)
    return ("Xero says: " + "; ".join(messages)) if messages else text[:600]


def xero_rows(result, key):
    if isinstance(result, dict):
        return result.get(key) or []
    if isinstance(result, list):
        return result
    return []


def xero_find_supplier(tenant_id, name, abn):
    """Existing contact by ABN (TaxNumber) first, then by normalised name. None when not found."""
    if not name:
        return None
    rows = xero_rows(xero_call("list_contacts", tenant_id, searchTerm=str(name)[:60]), "Contacts")
    abn_digits = "".join(ch for ch in str(abn or "") if ch.isdigit())
    if abn_digits:
        for c in rows:
            if "".join(ch for ch in str(c.get("TaxNumber") or "") if ch.isdigit()) == abn_digits:
                return c
    target = bk_norm(name)
    for c in rows:
        if bk_norm(c.get("Name")) == target:
            return c
    return None


def xero_chart(tenant_id):
    accounts = xero_rows(xero_call("list_accounts", tenant_id, where='Status=="ACTIVE"'), "Accounts")
    taxes = xero_rows(xero_call("list_tax_rates", tenant_id), "TaxRates")
    acc = [{"code": a.get("Code"), "name": a.get("Name"), "type": a.get("Type"),
            "description": (a.get("Description") or "")[:120]}
           for a in accounts if a.get("Code") and a.get("Type") in XERO_EXPENSE_TYPES]
    tax = [{"type": t.get("TaxType"), "name": t.get("Name"), "rate": t.get("EffectiveRate")}
           for t in taxes if t.get("Status", "ACTIVE") == "ACTIVE" and t.get("CanApplyToExpenses", True)]
    return acc, tax


def xero_bill_body(proposal, status):
    lines = []
    for ln in proposal.get("lines") or []:
        qty = ln.get("quantity") or 1
        unit = ln.get("unit_amount")
        if unit is None:
            unit = round((ln.get("line_amount") or 0) / qty, 4) if qty else (ln.get("line_amount") or 0)
        item = {"Description": (ln.get("description") or "")[:4000], "Quantity": qty, "UnitAmount": unit}
        if ln.get("account_code"):
            item["AccountCode"] = ln["account_code"]
        if ln.get("tax_type"):
            item["TaxType"] = ln["tax_type"]
        lines.append(item)
    body = {
        "Type": "ACCPAY",
        "Contact": {"ContactID": proposal["contact"]["id"]},
        "Date": proposal.get("date"),
        "LineAmountTypes": proposal.get("line_amount_types") or "Exclusive",
        "LineItems": lines,
        "Status": status,
    }
    for key, field in (("due_date", "DueDate"), ("invoice_number", "InvoiceNumber"),
                       ("reference", "Reference"), ("currency", "CurrencyCode")):
        if proposal.get(key):
            body[field] = proposal[key]
    return body


def xero_ensure_contact(tenant_id, proposal):
    contact = proposal.get("contact") or {}
    if contact.get("id"):
        return contact["id"]
    # An earlier attempt may have created the contact before Xero rejected the bill; reuse it.
    found = xero_find_supplier(tenant_id, contact.get("name"), contact.get("abn"))
    if found and found.get("ContactID"):
        proposal["contact"]["id"] = found["ContactID"]
        proposal["contact"]["is_new"] = False
        return found["ContactID"]
    body = {"Name": contact.get("name") or "Unknown supplier"}
    if contact.get("abn"):
        body["TaxNumber"] = contact["abn"]
    rows = xero_rows(xero_call("create_contact", tenant_id, contact=body), "Contacts")
    if not rows or not rows[0].get("ContactID"):
        raise RuntimeError("Xero did not return the new contact")
    proposal["contact"]["id"] = rows[0]["ContactID"]
    proposal["contact"]["is_new"] = False
    return rows[0]["ContactID"]


def xero_terms_due(terms, issue):
    """Due date from Xero payment terms ({"Day": n, "Type": ...}) for a bill dated `issue`, or None."""
    try:
        day = int(str((terms or {}).get("Day") or ""))
    except (TypeError, ValueError):
        return None
    kind = str((terms or {}).get("Type") or "")
    next_month = (issue.replace(day=1) + datetime.timedelta(days=32)).replace(day=1)
    if kind == "DAYSAFTERBILLDATE":
        return issue + datetime.timedelta(days=day)
    if kind == "DAYSAFTERBILLMONTH":
        return next_month - datetime.timedelta(days=1) + datetime.timedelta(days=day)
    if kind == "OFCURRENTMONTH":
        return issue.replace(day=min(max(day, 1), (next_month - datetime.timedelta(days=1)).day))
    if kind == "OFFOLLOWINGMONTH":
        after = (next_month + datetime.timedelta(days=32)).replace(day=1)
        return next_month.replace(day=min(max(day, 1), (after - datetime.timedelta(days=1)).day))
    return None


def xero_default_due(tenant_id, contact, issue_date):
    """(due date, where it came from) for a bill with no due date: the supplier's bill terms in Xero, then the
    organisation's default bill terms, then the bill date. ("", "") when the bill has no usable date."""
    try:
        issue = datetime.date.fromisoformat(str(issue_date or "")[:10])
    except ValueError:
        return "", ""
    due = xero_terms_due(((contact or {}).get("PaymentTerms") or {}).get("Bills"), issue)
    if due:
        return str(due), "the supplier's payment terms in Xero"
    try:
        org = xero_call("get_organisation", tenant_id)
        if isinstance(org, dict) and isinstance(org.get("Organisations"), list):
            org = org["Organisations"][0] if org["Organisations"] else {}
        elif isinstance(org, list):
            org = org[0] if org else {}
        due = xero_terms_due(((org or {}).get("PaymentTerms") or {}).get("Bills"), issue)
    except Exception:
        due = None
    if due:
        return str(due), "the organisation's default bill terms in Xero"
    return str(issue), "the invoice date, because no payment terms are set in Xero"


def xero_create_bill(tenant_id, proposal, status="DRAFT"):
    xero_ensure_contact(tenant_id, proposal)
    rows = xero_rows(xero_call("create_invoice", tenant_id, invoice=xero_bill_body(proposal, status)), "Invoices")
    if not rows or not rows[0].get("InvoiceID"):
        raise RuntimeError("Xero did not return the new bill")
    return rows[0]["InvoiceID"]


def xero_update_bill_lines(tenant_id, bill_id, proposal):
    body = xero_bill_body(proposal, "DRAFT")
    patch = {k: v for k, v in body.items() if k not in ("Type", "Status")}
    xero_call("update_invoice", tenant_id, invoiceId=bill_id, patch=patch)


def xero_set_status(tenant_id, bill_id, status):
    xero_call("update_invoice", tenant_id, invoiceId=bill_id, patch={"Status": status})


def xero_attach_pdf(tenant_id, bill_id, knowledge_path):
    """Attach the knowledge file to the bill. Returns '' on success or the error text."""
    try:
        local = api.files.get(file=knowledge_path)
        with open(local, "rb") as fh:
            content = base64.b64encode(fh.read()).decode("ascii")
        xero_call("upload_attachment", tenant_id, hostType="Invoices", hostId=bill_id,
                  fileName=knowledge_path.split("/")[-1], base64Content=content, mimeType="application/pdf")
        return ""
    except Exception as exc:
        return str(exc)[:300]


def xero_bill_link(bill_id):
    return "https://go.xero.com/AccountsPayable/Edit.aspx?InvoiceID=" + str(bill_id)


def xero_bill_markdown(proposal, warnings=None, blocking=None, bill_id="", file_path="", client_name=""):
    """The review item's description: what the AI read, how it coded it, and what to check."""
    p = proposal or {}
    c = p.get("contact") or {}
    cur = p.get("currency") or ""
    out = []
    out.append("**" + (c.get("name") or "Unknown supplier") + "**" + (" (new supplier)" if c.get("is_new") else "")
               + (" for " + client_name if client_name else ""))
    out.append("")
    out.append("- Invoice " + (p.get("invoice_number") or "—") + ", dated " + (p.get("date") or "—")
               + ", due " + (p.get("due_date") or "—"))
    out.append("- Total " + bk_fmt(p.get("total"), cur) + " (GST " + bk_fmt(p.get("tax"), cur) + ", amounts "
               + ("include" if p.get("line_amount_types") == "Inclusive" else "exclude") + " GST)")
    if bill_id:
        out.append("- Draft bill in Xero: [open in Xero](" + xero_bill_link(bill_id) + ")")
    else:
        out.append("- Not in Xero yet: the bill is created when you approve")
    if file_path:
        out.append("- PDF: `" + file_path + "` in Knowledge")
    out.append("")
    out.append("**Lines**")
    out.append("")
    # A list, not a table: WorkQ descriptions don't render markdown tables.
    for i, ln in enumerate(p.get("lines") or []):
        desc = str(ln.get("description") or "").replace("\n", " ")[:120]
        out.append("- Line " + str(i + 1) + ": " + desc + ", " + bk_fmt(ln.get("line_amount"), cur) + ". Account **"
                   + (ln.get("account_code") or "missing") + "**, tax " + (ln.get("tax_type") or "—") + ". "
                   + str(ln.get("reason") or "")[:160] + " (" + str(ln.get("confidence") or "low") + " confidence)")
    if blocking:
        out.append("")
        out.append("**Must fix before approving**")
        out.extend("- " + b for b in blocking)
    if warnings:
        out.append("")
        out.append("**Check**")
        out.extend("- " + w for w in warnings)
    out.append("")
    out.append("Fill in the **Bill review** form on this item to approve, change, reject or ask the client.")
    return "\n".join(out)


# ── Apply the decision in Xero ──


CHANGES_PROMPT = (
    "A bookkeeper reviewed a draft supplier bill and wrote the changes they want in plain words. Turn them into "
    "structured edits against 'bill'. Line numbers in the text are 1-based; 'index' in your output is 0-based. "
    "'all lines' means every line. Only use account codes from 'accounts' and tax types from 'tax_rates'. Leave out "
    "anything the bookkeeper didn't ask to change."
)
CHANGES_HINT = ('{"lines": [{"index": 0, "account_code": "449", "tax_type": "INPUT", "description": null, '
                '"line_amount": null}], "due_date": null, "invoice_number": null, "date": null, "reference": null}')
EMAIL_PROMPT = (
    "Draft a short, friendly email from an Australian bookkeeper to a small-business owner. Plain text, no subject "
    "line, sign off as the bookkeeping team. Use only the facts given. Purpose: "
)

problem = params.get("problem") or ""
ctx = params.get("ctx") or {}
decision = params.get("decision") or {}
settings = ctx.get("settings") or {}
client = ctx.get("client") or {}
record = dict(ctx.get("record") or {})
record_todo = ctx.get("record_todo") or ""
outcome = ""
followup_id = ""
changed_coding = False

if not problem:
    try:
        tenant = record["tenant_id"]
        proposal = record.get("proposal") or {}
        bill_id = record.get("bill_id") or ""
        action = decision.get("action")
        today = bk_today(settings)
        actor = decision.get("actor") or bk_reviewer(settings, client)
        c = proposal.get("contact") or {}
        facts = {
            "business": client.get("name"), "owner_name": client.get("contact_name"), "supplier": c.get("name"),
            "invoice_number": proposal.get("invoice_number"), "date": proposal.get("date"),
            "total": bk_fmt(proposal.get("total"), proposal.get("currency") or ""), "note": decision.get("notes"),
        }

        if action == "approve_changes" and decision.get("changes"):
            accounts, taxes = xero_chart(tenant)
            codes = {a["code"] for a in accounts}
            tax_types = {t["type"] for t in taxes}
            edits = api.ai.extract(
                prompt=CHANGES_PROMPT,
                input=json.dumps({"changes": decision["changes"], "bill": proposal, "accounts": accounts[:300],
                                  "tax_rates": taxes})[:30000],
                schema_hint=CHANGES_HINT,
            )
            edits = edits if isinstance(edits, dict) else {}
            for e in edits.get("lines") or []:
                i = e.get("index") if isinstance(e, dict) else None
                if not isinstance(i, (int, float)) or not (0 <= int(i) < len(proposal.get("lines") or [])):
                    continue
                ln = proposal["lines"][int(i)]
                if e.get("account_code") and str(e["account_code"]) in codes:
                    ln["account_code"] = str(e["account_code"])
                    changed_coding = True
                if e.get("tax_type") and str(e["tax_type"]) in tax_types:
                    ln["tax_type"] = str(e["tax_type"])
                    changed_coding = True
                if e.get("description"):
                    ln["description"] = str(e["description"])[:400]
                amount = bk_money(e.get("line_amount"))
                if amount is not None:
                    ln["line_amount"] = amount
                    ln["unit_amount"] = round(amount / (ln.get("quantity") or 1), 4)
                ln["source"] = "reviewer"
                ln["reason"] = "Changed by the reviewer"
            for key in ("due_date", "invoice_number", "date", "reference"):
                if edits.get(key):
                    proposal[key] = str(edits[key])
            record["proposal"] = proposal
            if bill_id:
                xero_update_bill_lines(tenant, bill_id, proposal)

        approving = action in ("approve", "approve_changes", "client_approved")
        missing = [i + 1 for i, ln in enumerate(proposal.get("lines") or []) if not ln.get("account_code")]
        if approving and missing:
            raise RuntimeError("line(s) " + ", ".join(str(m) for m in missing) + " still have no account code. "
                               "Submit the review again with \"Approve with changes\" and the account codes")

        if approving:
            limit = bk_money(client.get("client_approval_above"))
            if limit is None:
                limit = bk_money(settings.get("client_approval_above"))
            total = proposal.get("total") or 0
            if action == "client_approved":
                record["client_approved"] = True
            if limit and total > limit and not record.get("client_approved"):
                email = api.ai.generate(prompt=EMAIL_PROMPT + "ask them to approve this bill before it is approved in Xero.",
                                        input=json.dumps(facts))
                item = api.workq.create(
                    title=("Get approval from " + (client.get("name") or "the client") + ": " + (c.get("name") or "bill")
                           + " " + facts["total"])[:200],
                    scope="org",
                    description=("This bill is over the client-approval limit (" + bk_fmt(limit) + ").\n\n"
                                 "1. Email " + (client.get("contact_name") or "the business owner")
                                 + (" (" + client["contact_email"] + ")" if client.get("contact_email") else "")
                                 + " using the draft below.\n2. When they reply, fill in the **Client bill approval** form on this item.\n\n"
                                 "**Draft email**\n\n" + email),
                    priority="high",
                    due_date=str(bk_add_business_days(today, 3)),
                    assignee_ids=[actor] if actor else None,
                    labels=["bookkeeping", "client-approval", client.get("slug", "")],
                )
                api.workq.attach_form(todo_id=item["id"], form_id=params["approval_form"])
                bk_write_json(BK_BILLS + "/" + item["id"] + ".json", {"link": record_todo})
                followup_id = item["id"]
                record["status"] = "awaiting_client"
                outcome = "client_approval_requested"
            else:
                status = settings.get("approved_status") or "SUBMITTED"
                if not proposal.get("due_date") and proposal.get("date"):
                    # Xero only accepts a submitted or approved bill with a due date.
                    due, came_from = xero_default_due(tenant, None, proposal["date"])
                    if due:
                        proposal["due_date"] = due
                        record["proposal"] = proposal
                        record.setdefault("warnings", []).append("Due date set to " + due + " from " + came_from + ".")
                        if bill_id:
                            xero_update_bill_lines(tenant, bill_id, proposal)
                if not bill_id:
                    bill_id = xero_create_bill(tenant, proposal, status)
                    record["bill_id"] = bill_id
                    record["attach_error"] = xero_attach_pdf(tenant, bill_id, record.get("file") or "")
                else:
                    xero_set_status(tenant, bill_id, status)
                record["status"] = "approved"
                record["approved_by"] = decision.get("actor") or ""
                outcome = "approved"

        elif action in ("reject", "client_rejected"):
            if bill_id:
                xero_set_status(tenant, bill_id, "DELETED")
            record["status"] = "rejected"
            outcome = "rejected"

        elif action in ("ask", "client_question"):
            if action == "ask":
                purpose = "ask them this question about a supplier bill: " + (decision.get("notes") or "please confirm the bill")
            else:
                purpose = ("reply to their question about a supplier bill and confirm next steps. Their message: "
                           + (decision.get("notes") or ""))
            email = api.ai.generate(prompt=EMAIL_PROMPT + purpose, input=json.dumps(facts))
            item = api.workq.create(
                title=("Ask " + (client.get("name") or "the client") + " about " + (c.get("name") or "a bill") + " "
                       + (proposal.get("invoice_number") or ""))[:200],
                scope="org",
                description=("1. Email " + (client.get("contact_name") or "the business owner")
                             + (" (" + client["contact_email"] + ")" if client.get("contact_email") else "")
                             + " using the draft below.\n2. When they answer, fill in the **Bill review** form on this item.\n\n"
                             "**Draft email**\n\n" + email + "\n\n---\n\n"
                             + xero_bill_markdown(proposal, record.get("warnings"), record.get("blocking"), bill_id,
                                                  record.get("file") or "", client.get("name", ""))),
                priority="medium",
                due_date=str(bk_add_business_days(today, 3)),
                assignee_ids=[actor] if actor else None,
                labels=["bookkeeping", "client-query", client.get("slug", "")],
            )
            api.workq.attach_form(todo_id=item["id"], form_id=params["review_form"])
            bk_write_json(BK_BILLS + "/" + item["id"] + ".json", {"link": record_todo})
            followup_id = item["id"]
            record["status"] = "waiting_client"
            outcome = "question_drafted"

        record.setdefault("history", []).append({"at": bk_now_iso(settings), "by": decision.get("actor") or "",
                                                  "action": action, "outcome": outcome,
                                                  "notes": decision.get("notes") or ""})
        bk_write_json(BK_BILLS + "/" + record_todo + ".json", record)
    except Exception as exc:
        problem = "Couldn't apply this review in Xero. " + str(exc)[:600]

